/* AbiLearn — Social Science Extra MCQs — Ch 5, 6, 9, 10 (200 harder Questions) */

const SOCIAL_CH5_EXTRA = [
  { q: 'The World Bank classifies countries as "high income" if per capita GNI exceeds:', opts: ['$5,000', '$8,000', '$12,056', '$20,000'], ans: 2, exp: 'World Bank 2019 criterion: per capita GNI above $12,056 = high income/developed country. India\'s was about $2,000 — lower-middle income.' },
  { q: 'The Human Development Index was created by UNDP in:', opts: ['1980', '1990', '2000', '2005'], ans: 1, exp: 'HDI was launched by UNDP in 1990, developed by Pakistani economist Mahbub ul Haq with support from Amartya Sen, to measure development beyond income.' },
  { q: 'Which Pakistani economist co-created the Human Development Index?', opts: ['Amartya Sen', 'Muhammad Yunus', 'Mahbub ul Haq', 'Pervez Hoodbhoy'], ans: 2, exp: 'Mahbub ul Haq (Pakistan) developed the HDI concept with Amartya Sen\'s (India) intellectual support, published in UNDP\'s first Human Development Report (1990).' },
  { q: 'Amartya Sen won the Nobel Prize in Economics in:', opts: ['1990', '1998', '2006', '2010'], ans: 1, exp: 'Amartya Sen won the Nobel Prize in Economics in 1998 for his contributions to welfare economics, social choice theory, and the analysis of poverty and famine.' },
  { q: 'Infant Mortality Rate (IMR) measures:', opts: ['Total number of infant deaths in a year', 'Number of children dying before age 5 per 1000 births', 'Number of children dying before age 1 per 1000 live births', 'Percentage of infants who survive the first year'], ans: 2, exp: 'IMR = number of children who die before reaching 1 year of age per 1000 live births in a given year. Kerala has India\'s lowest IMR (~12); national average is around 28-30.' },
  { q: 'Net Attendance Ratio measures:', opts: ['Total enrolment in all schools', 'Percentage of children 6-10 years actually attending school', 'Number of teachers per 100 students', 'Percentage of children who pass exams'], ans: 1, exp: 'Net Attendance Ratio = percentage of children in the 6-10 age group who attend school. It measures actual attendance (not just enrolment), reflecting access to education.' },
  { q: 'Body Mass Index (BMI) is calculated as:', opts: ['Weight (kg) + Height (m)', 'Weight (kg) / Height (m)²', 'Height (m) / Weight (kg)', 'Weight (kg) × Height (m)'], ans: 1, exp: 'BMI = weight in kilograms divided by height in metres squared. BMI under 18.5 = undernourished; 18.5-24.9 = normal; 25-29.9 = overweight; 30+ = obese.' },
  { q: 'A BMI of less than 18.5 indicates a person is:', opts: ['Normal weight', 'Overweight', 'Malnourished/undernourished', 'Obese'], ans: 2, exp: 'BMI below 18.5 indicates undernutrition/malnourishment. In developing countries, this is common due to poverty and food insecurity.' },
  { q: 'Literacy Rate in India is calculated for people aged:', opts: ['5 years and above', '6 years and above', '7 years and above', '15 years and above'], ans: 2, exp: 'India\'s literacy rate counts people aged 7 years and above who can read and write with understanding in any language.' },
  { q: 'Kerala\'s literacy rate compared to Bihar is approximately:', opts: ['Kerala 60%, Bihar 75%', 'Kerala 94%, Bihar 64%', 'Kerala 80%, Bihar 80%', 'Kerala 70%, Bihar 50%'], ans: 1, exp: 'Kerala has India\'s highest literacy rate (94%+) while Bihar has one of the lowest (~64% as per 2011 census). Despite this, Kerala\'s per capita income is lower than Punjab.' },
  { q: 'The HDI considers which three dimensions of human development?', opts: ['Income, education, and political freedom', 'Health (life expectancy), education (years of schooling), and standard of living (GNI per capita PPP)', 'Employment, GDP, and gender equality', 'Food security, health, and political stability'], ans: 1, exp: 'HDI combines: (1) Long and healthy life — life expectancy at birth; (2) Knowledge — mean/expected years of schooling; (3) Decent living standard — GNI per capita (PPP).' },
  { q: 'India\'s HDI rank in the 2019 Human Development Report was approximately:', opts: ['50th', '100th', '131st', '160th'], ans: 2, exp: 'India ranked 131 out of 189 countries in the 2019 HDI Report, in the medium human development category.' },
  { q: 'Sustainable development was defined by the Brundtland Commission as:', opts: ['Using resources without wasting any', 'Meeting present needs without compromising future generations\' ability to meet their own needs', 'Using only renewable energy sources', 'Eliminating poverty in one generation'], ans: 1, exp: 'Brundtland Commission (1987, "Our Common Future"): "Sustainable development is development that meets the needs of the present without compromising the ability of future generations to meet their own needs."' },
  { q: 'Negative externalities in production refer to:', opts: ['Losses made by the company', 'Costs imposed on third parties not directly involved in production (like pollution affecting neighbours)', 'Taxes paid by producers', 'Reduced profits due to competition'], ans: 1, exp: 'Negative externalities are costs borne by third parties — a factory polluting a river imposes costs on downstream communities who must purify water or forego fishing, but the factory doesn\'t pay for this.' },
  { q: 'The MGNREGA 2005 guarantees:', opts: ['50 days of employment to all citizens', '100 days of employment to rural households willing to do unskilled manual work', 'Employment to all urban poor', 'Permanent government jobs to SC/ST'], ans: 1, exp: 'MGNREGA (Mahatma Gandhi National Rural Employment Guarantee Act 2005) guarantees 100 days of paid employment per year to each rural household whose members are willing to do unskilled manual work.' },
  { q: 'The "Kerala Model" of development is significant because Kerala has:', opts: ['The highest per capita income in India', 'Lower per capita income but much better health and education indicators than richer states', 'The largest industrial base in India', 'The highest FDI in India'], ans: 1, exp: 'Kerala\'s per capita income is lower than Punjab/Haryana, but its HDI indicators (literacy 94%+, IMR ~12, life expectancy 74+) are comparable to developed nations — showing social investment matters more than income alone.' },
  { q: 'Per capita income as a development indicator has limitations because it:', opts: ['Is difficult to calculate', 'Hides inequality (distribution), environmental costs, and non-material aspects of wellbeing', 'Only measures agricultural output', 'Includes informal sector poorly'], ans: 1, exp: 'Per capita income = total income divided by population. A high average can hide extreme inequality (10 very rich, 90 very poor). It also ignores pollution, social services, freedoms, and life satisfaction.' },
  { q: 'The Gini Coefficient measures:', opts: ['Economic growth rate', 'Income inequality (0 = perfect equality; 1 = complete inequality)', 'Human development levels', 'Inflation rate'], ans: 1, exp: 'Gini Coefficient ranges from 0 (everyone has equal income) to 1 (one person has all income). India\'s Gini is approximately 0.35, indicating moderate inequality.' },
  { q: 'Renewable resources are different from non-renewable resources because:', opts: ['Renewable resources are always free', 'Renewable resources can regenerate naturally within a human time scale; non-renewable cannot', 'Renewable resources are found only in developed countries', 'Non-renewable resources are also called sustainable resources'], ans: 1, exp: 'Renewable resources (solar, wind, water, forests) can naturally regenerate. Non-renewable resources (coal, petroleum, natural gas, minerals) took millions of years to form and will run out if overused.' },
  { q: 'The "National Food Security Act 2013" provides to eligible households:', opts: ['Free land and housing', '5 kg of food grain per person per month at highly subsidised rates of ₹1-3/kg', 'Free meals in community kitchens', 'Cash transfers of ₹2000/month'], ans: 1, exp: 'NFSA 2013: entitled beneficiaries get 5 kg rice/wheat/coarse grains per person per month at ₹1 (coarse grains), ₹2 (wheat), or ₹3 (rice) per kg — covering 75% rural + 50% urban population.' },
  { q: 'Sri Lanka has a higher HDI than India primarily because:', opts: ['Sri Lanka is wealthier', 'Sri Lanka invested heavily in education and health, achieving high literacy and low IMR early', 'Sri Lanka received more foreign aid', 'Sri Lanka had no civil war'], ans: 1, exp: 'Sri Lanka (HDI rank ~72) outperforms India (131) despite being a smaller, poorer economy historically, because it made early investments in universal education and healthcare.' },
  { q: 'Amartya Sen\'s book "Development as Freedom" argues:', opts: ['Development requires restricted political freedoms', 'Development means expanding people\'s real freedoms (capability approach), not just increasing incomes', 'Freedom is incompatible with economic development', 'Only economic freedom matters for development'], ans: 1, exp: 'Amartya Sen argues development should be understood as expanding people\'s substantive freedoms — to live long, be educated, participate in politics, and have economic security — not just increasing GDP.' },
  { q: 'Why is life expectancy at birth considered a better development indicator than IMR alone?', opts: ['Life expectancy ignores children', 'Life expectancy captures health outcomes across all age groups, not just infants', 'Life expectancy is easier to measure', 'IMR is not a reliable measure'], ans: 1, exp: 'Life expectancy at birth measures the average number of years a newborn is expected to live, reflecting healthcare quality, nutrition, and living conditions across all ages, not just infant care.' },
  { q: 'The Genuine Progress Indicator (GPI) differs from GDP by:', opts: ['Measuring only industrial output', 'Including social benefits and subtracting social costs (pollution, crime, inequality) from economic activity', 'Measuring only agricultural output', 'Excluding government spending'], ans: 1, exp: 'GPI adjusts GDP by adding positive contributions (volunteer work, education) and subtracting negative ones (pollution costs, crime, income inequality) to better measure actual societal wellbeing.' },
  { q: 'What does "development for one may be destruction for another" mean in the context of development goals?', opts: ['Countries that develop destroy other countries', 'Different people have different and sometimes conflicting developmental goals (e.g., dam benefits city, floods tribal village)', 'Development always causes environmental destruction', 'Only one country can develop at a time'], ans: 1, exp: 'A dam may generate electricity and irrigate farms (development for city/farmers) but flood tribal villages and forests (destruction for tribals). Development goals conflict between different groups.' },
  { q: 'Public Distribution System (PDS) in India provides:', opts: ['Free healthcare at government hospitals', 'Subsidised food grains, kerosene, and sugar through ration shops', 'Free education from class 1-12', 'Cash transfers to BPL families'], ans: 1, exp: 'PDS distributes subsidised food grains (rice, wheat), sugar, kerosene, and other essentials through a network of Fair Price Shops (ration shops) to below-poverty-line (BPL) and priority households.' },
  { q: 'An environmental indicator of sustainable development would measure:', opts: ['GDP growth rate', 'Forest cover, air quality, water availability, and species diversity', 'Per capita income', 'Literacy rate'], ans: 1, exp: 'Environmental sustainability indicators include: forest cover, CO₂ emissions, fresh water availability, biodiversity/species count, soil quality, and ocean health — measuring if the natural base is being maintained.' },
  { q: 'If a country has high per capita income but high infant mortality, it suggests:', opts: ['Good development in all areas', 'Income gains are not reaching the poor or being invested in public health', 'The data is incorrect', 'High IMR is normal at high incomes'], ans: 1, exp: 'High income + high IMR indicates income inequality and/or failure to invest income in public health infrastructure, reaching the poor. Many Middle Eastern oil states had this pattern initially.' },
  { q: 'The concept of "human poverty" as opposed to "income poverty" focuses on:', opts: ['People with no money', 'Deprivation in basic capabilities — health, education, social participation — regardless of income', 'People below the official poverty line', 'Poverty in rural areas only'], ans: 1, exp: 'Human poverty (Amartya Sen, UNDP) focuses on capability deprivation — being unable to live a long healthy life, access education, or participate in society — even if a person has some income.' },
  { q: 'MGNREGA payment of wages must be made within:', opts: ['1 week', '15 days', '1 month', '45 days'], ans: 1, exp: 'MGNREGA requires wages to be paid within 15 days of work completion. If payment is delayed beyond 15 days, workers are entitled to a compensation/unemployment allowance.' },
  { q: 'Which of the following is a non-economic goal of development?', opts: ['Higher per capita income', 'Better roads and transport', 'Equal treatment and dignity of all citizens regardless of caste or gender', 'More factories and industries'], ans: 2, exp: 'Non-economic development goals include: equality, social freedom, dignity, non-discrimination, political participation, cultural identity, and security — things money cannot fully buy.' },
  { q: 'When comparing development across countries, per capita income alone is inadequate because:', opts: ['It\'s hard to convert currencies accurately', 'Countries may have same average income but vastly different quality of life, inequality, and freedoms', 'Only rich countries can calculate it properly', 'It doesn\'t count informal sector'], ans: 1, exp: 'Two countries may have the same per capita income but one may have universal healthcare and education while the other has extreme poverty alongside wealth. Income averages hide distribution and social investment.' },
  { q: 'The concept of "capability approach" in development economics was developed by:', opts: ['Mahbub ul Haq', 'Amartya Sen', 'John Rawls', 'Paul Samuelson'], ans: 1, exp: 'Amartya Sen developed the "capability approach" — the idea that development should focus on expanding people\'s capabilities (what they can do and be), not just their income or utility.' },
  { q: 'Why is the HDI considered superior to per capita income as a development indicator?', opts: ['HDI is easier to calculate', 'HDI captures multiple dimensions of wellbeing (health, education, income), not just one', 'HDI measures only education and ignores income', 'HDI is calculated by a UN body'], ans: 1, exp: 'HDI captures health (life expectancy), education (schooling years), AND income (GNI per capita) — a multidimensional measure. Countries like Kerala score lower on income but higher on health/education, better reflecting reality.' },
  { q: 'In India, per capita income of Punjab is higher than Kerala, but Kerala\'s HDI is higher. This demonstrates:', opts: ['Punjab\'s data is incorrect', 'Income alone doesn\'t determine human development — social investments in health and education matter more', 'Kerala receives more central government funds', 'Punjab is underpopulated'], ans: 1, exp: 'Kerala invests heavily in public education and healthcare (historical legacy of princely state policy + communist state government priorities), achieving better human development despite lower income.' },
  { q: 'The MGNREGA is also known as:', opts: ['Operation Flood', 'Rural Job Guarantee Scheme', 'National Rural Employment Guarantee Act', 'Pradhan Mantri Rozgar Yojana'], ans: 2, exp: 'MGNREGA = Mahatma Gandhi National Rural Employment Guarantee Act (2005). "Mahatma Gandhi" was prefixed in 2009. It is also called NREGA or the "Job Guarantee Scheme."' },
  { q: 'What does "environmental sustainability" require of present-day economic activities?', opts: ['Total halt of all industrial production', 'Ensuring resource use today does not deplete or degrade the environment beyond its regenerative capacity', 'Using only solar and wind energy', 'Returning to pre-industrial lifestyles'], ans: 1, exp: 'Environmental sustainability requires that present-day resource use, pollution, and land degradation don\'t exceed the natural system\'s capacity to regenerate and absorb waste — preserving options for future generations.' },
  { q: 'Gross Enrolment Ratio (GER) measures:', opts: ['Net enrolment at primary level', 'Total enrolment in a level of education as % of the eligible age group population', 'Number of teachers enrolled for training', 'Students who complete their education'], ans: 1, exp: 'GER = (total enrolment in a level, regardless of age) / (population of official age group for that level) × 100. Can exceed 100% if overage/underage students are enrolled.' },
  { q: 'Bihar\'s lower HDI compared to Kerala reflects primarily:', opts: ['Geographical isolation', 'Historical underinvestment in health and education, combined with high poverty rates', 'Smaller population', 'Less foreign investment'], ans: 1, exp: 'Bihar has struggled with low investment in public services (schools, hospitals), high poverty, caste-based discrimination, and historical neglect — resulting in lower literacy, higher IMR, and shorter life expectancy.' },
  { q: 'Development that meets present needs without compromising future needs is called:', opts: ['Inclusive development', 'Sustainable development', 'Human development', 'Equitable development'], ans: 1, exp: 'Sustainable Development (Brundtland Commission 1987) = meeting present needs without compromising future generations\' ability to meet their own needs. It balances economic, social, and environmental goals.' },
  { q: 'Which statement about development is most accurate?', opts: ['Economic growth automatically leads to human development', 'Development requires both economic growth AND distribution to ensure all people benefit', 'Only GDP matters for measuring development', 'Poorer countries cannot achieve high human development'], ans: 1, exp: 'Economic growth is necessary but not sufficient for human development. Growth must be accompanied by social investment in health, education, and equity — as the Kerala vs Bihar comparison shows.' },
  { q: 'The term "below poverty line" (BPL) in India is defined based on:', opts: ['Land ownership only', 'Caloric intake and/or income below a minimum threshold set by government', 'Whether a family has a house', 'Number of children in family'], ans: 1, exp: 'BPL is defined by the Planning Commission/NITI Aayog based on per capita monthly expenditure: those below a threshold (varying by state) are classified BPL and eligible for government welfare schemes.' },
  { q: 'Why do Kerala\'s health outcomes (low IMR, high life expectancy) explain more than Kerala\'s income?', opts: ['Kerala has a special climate that reduces disease', 'Kerala\'s history of high literacy (especially women\'s literacy) leads to better health practices and service utilisation', 'Kerala has less population pressure', 'The central government funds Kerala\'s health more'], ans: 1, exp: 'High female literacy in Kerala (result of 19th-century Travancore/Cochin state investment in education) leads to better child healthcare, nutrition, vaccination uptake, and family planning — explaining the health-income gap.' },
  { q: 'Inclusive growth means economic growth that:', opts: ['Grows the GDP very fast', 'Benefits all sections of society, reducing poverty and inequality alongside economic expansion', 'Includes only urban populations', 'Focuses only on agricultural growth'], ans: 1, exp: 'Inclusive growth requires that the benefits of economic expansion reach the poor and marginalised — through jobs, better wages, social services, and reduced inequality — not just GDP statistics.' },
  { q: 'The term "HDI" was first used in which publication?', opts: ['World Development Report (World Bank 1990)', 'Human Development Report (UNDP 1990)', 'Amartya Sen\'s Development as Freedom (1999)', 'Brundtland Report (1987)'], ans: 1, exp: 'HDI was first published in UNDP\'s Human Development Report 1990, conceived by Mahbub ul Haq. UNDP has published this annual report every year since 1990.' },
  { q: 'Life expectancy at birth in Kerala (approximately 74 years) compared to national average (approximately 69 years) demonstrates:', opts: ['Kerala\'s warmer climate', 'Kerala\'s superior public health investment, nutrition, and female empowerment over decades', 'Kerala receives more hospital funding from Centre', 'Kerala\'s smaller population'], ans: 1, exp: 'Kerala\'s higher life expectancy results from decades of investment in public health (village hospitals, PHCs), high female literacy (leading to better family health decisions), low IMR, and strong social safety nets.' },
  { q: 'The concept of "well-being" in development includes:', opts: ['Only material consumption', 'Economic security, health, education, freedom, dignity, equality, and social participation', 'GDP per capita only', 'Industrial output per person'], ans: 1, exp: 'Well-being in development encompasses multiple dimensions: material (income, food), physical (health), mental (education, meaning), social (relationships, participation), and political (freedom, voice) aspects.' },
  { q: 'An economy that uses only renewable resources and fully recycles waste is called:', opts: ['A developed economy', 'A circular economy', 'A mixed economy', 'A subsistence economy'], ans: 1, exp: 'A circular economy aims to eliminate waste by keeping resources in use (recycling, refurbishing) and regenerating natural systems — the opposite of the linear "take-make-dispose" economy.' }
];

const SOCIAL_CH6_EXTRA = [
  { q: 'The "double coincidence of wants" is a problem with the barter system because:', opts: ['Both parties must agree on price', 'Person A must want what B has AND B must want what A has — unlikely for complex economies', 'Goods cannot be divided', 'There are too many goods to trade'], ans: 1, exp: 'In barter, exchange requires both parties to simultaneously want what the other offers. In a complex economy with thousands of goods and millions of people, this coincidence is rare.' },
  { q: 'Money acts as a "store of value" means:', opts: ['Money keeps inflation low', 'Money can be saved and used for future transactions without losing its purchasing power', 'Banks store physical money safely', 'Gold stored in vaults backs every rupee'], ans: 1, exp: 'Money\'s store of value function allows people to save earnings now for future use. Unlike perishable goods in barter, money maintains value over time (though inflation can erode it).' },
  { q: 'Money acts as a "unit of account" means:', opts: ['Banks count money daily', 'Money provides a standard measure of value, allowing prices to be expressed uniformly', 'Government counts how much money exists', 'Exchange rate converts currencies'], ans: 1, exp: 'Unit of account = money provides a standard way to measure and express the value of all goods and services. Without this, we\'d need separate exchange ratios for every pair of goods.' },
  { q: 'In India, currency notes are issued by:', opts: ['Government of India', 'State Bank of India', 'Reserve Bank of India', 'Finance Commission'], ans: 2, exp: 'Currency notes in India are issued and managed by the Reserve Bank of India (RBI), signed by the RBI Governor. Coins are issued by the Government of India (Finance Ministry).' },
  { q: 'The ₹1 note in India is unusual because it is issued by:', opts: ['RBI like all other notes', 'Government of India (Ministry of Finance)', 'State Bank of India', 'Planning Commission'], ans: 1, exp: 'The ₹1 note is the only currency note issued by the Government of India (Finance Ministry), signed by the Finance Secretary. All other notes (₹2 and above) are issued by RBI.' },
  { q: 'Demand deposits are included in the money supply because:', opts: ['They earn interest like fixed deposits', 'They can be withdrawn on demand using cheques, functioning like money', 'They are issued by RBI', 'They are backed by gold'], ans: 1, exp: 'Demand deposits (current/savings accounts) can be withdrawn at any time using cheques — they function as money because payments can be made by cheque. They form part of M1 money supply.' },
  { q: 'The Cash Reserve Ratio (CRR) is the fraction of deposits that banks must:', opts: ['Lend to priority sectors', 'Keep in reserve with RBI, unable to lend', 'Pay as interest to depositors', 'Invest in government securities'], ans: 1, exp: 'CRR is the mandatory proportion of total deposits commercial banks must keep as reserves with the RBI. This money cannot be lent out, controlling how much credit banks can create.' },
  { q: 'Collateral in a loan agreement serves as:', opts: ['The interest rate charged', 'An asset pledged as security by the borrower, which the lender can seize if loan is unpaid', 'A guarantor who signs the loan agreement', 'The duration of the loan'], ans: 1, exp: 'Collateral = security asset (land title, gold, vehicle, crop) pledged by borrower. If borrower defaults, lender can seize and sell collateral to recover the loan amount.' },
  { q: 'Formal sector credit in India is regulated by:', opts: ['State governments', 'Finance Commission', 'Reserve Bank of India', 'SEBI'], ans: 2, exp: 'Formal sector credit (commercial banks, cooperative banks, microfinance institutions) is regulated by RBI, which sets interest rate policies, capital requirements, and lending guidelines.' },
  { q: 'Why do moneylenders in the informal sector charge much higher interest than banks?', opts: ['They take more risk with no regulation, and can because borrowers have no alternative', 'They have to pay high taxes', 'Bank interest rates are government-controlled', 'Moneylenders have higher operating costs'], ans: 0, exp: 'Informal moneylenders face no regulation, have monopolistic power in villages, and serve borrowers with no collateral who can\'t access banks. They exploit desperation and lack of competition to charge 20-100%+ interest.' },
  { q: 'Self Help Groups (SHGs) in India typically consist of:', opts: ['30-50 wealthy farmers forming a bank', '10-20 (typically 15-20) rural women who save regularly and provide credit to members', 'Government officials managing village funds', 'Corporations supporting rural development'], ans: 1, exp: 'SHGs are small (15-20 members, mostly women) informal savings and credit groups. Members save regularly, accumulate a fund, and give small loans to each other at moderate interest (10-15%).' },
  { q: 'What is the primary advantage of SHGs over moneylenders for rural poor?', opts: ['SHGs offer higher loan amounts', 'SHGs provide credit without collateral at lower interest rates, with collective decision-making and empowerment', 'SHGs are government-funded', 'SHGs offer 24/7 access to funds'], ans: 1, exp: 'SHGs provide collateral-free loans at 10-15% interest (vs 20-100% from moneylenders), decision-making power to women, social support, and linkage to bank credit — transformative for rural poor women.' },
  { q: 'Grameen Bank was founded by Muhammad Yunus in Bangladesh in:', opts: ['1974', '1980', '1983', '1990'], ans: 2, exp: 'Muhammad Yunus founded Grameen Bank in Bangladesh in 1983 (officially incorporated; began as a project in 1976). It pioneered microcredit — collateral-free small loans to the rural poor, mostly women.' },
  { q: 'Muhammad Yunus won the Nobel Peace Prize in:', opts: ['1998', '2001', '2006', '2010'], ans: 2, exp: 'Muhammad Yunus (and Grameen Bank) won the Nobel Peace Prize in 2006 for their efforts to create economic and social development from below, and for pioneering the microcredit movement globally.' },
  { q: 'Grameen Bank\'s repayment rate is notably high (95%+) because:', opts: ['Borrowers are forced by law to repay', 'Group lending creates social pressure — members of the group are collectively responsible, incentivising repayment', 'Loans are very small so easy to repay', 'Government guarantees the loans'], ans: 1, exp: 'Grameen Bank uses "group lending" — loans to individuals within groups where members are jointly responsible. Social pressure from group members and the prospect of future credit ensure very high repayment rates.' },
  { q: 'NABARD stands for:', opts: ['National Agriculture Bank and Rural Development', 'National Bank for Agriculture and Rural Development', 'National Association for Banking and Rural Dynamics', 'National Authority for Banking and Rural Districts'], ans: 1, exp: 'NABARD = National Bank for Agriculture and Rural Development. Established 1982, it is the apex development bank that refinances rural banks, promotes SHGs, and supports rural credit and development.' },
  { q: 'SIDBI was established to promote:', opts: ['Large steel industries', 'Small and medium industries and entrepreneurs', 'Silicon Valley type IT industries', 'Sugar and dairy industries'], ans: 1, exp: 'SIDBI = Small Industries Development Bank of India. Established 1990, it provides financial support to micro, small, and medium enterprises (MSMEs) through refinancing and direct lending.' },
  { q: 'A "debt trap" in informal credit occurs when:', opts: ['Banks refuse to lend more', 'A borrower takes new loans to repay old ones, increasing total debt beyond ability to repay', 'Interest rates are fixed by law', 'Collateral is seized by moneylender'], ans: 1, exp: 'A debt trap: high informal interest rates mean borrowers spend all income on interest without reducing principal. They take new loans to survive, accumulating debt that can eventually consume all assets (land, livestock).' },
  { q: 'Priority Sector Lending (PSL) requires banks to lend at least what percentage to priority sectors?', opts: ['25%', '33%', '40%', '50%'], ans: 2, exp: 'RBI mandates commercial banks to lend at least 40% of net bank credit to priority sectors: agriculture, MSMEs, housing (affordable), education, export, and weaker sections.' },
  { q: 'Kissan Credit Card (KCC) is primarily designed to provide:', opts: ['Permanent credit facility to non-farmers', 'Short-term crop loans and agricultural input credit to farmers', 'Housing loans to rural poor', 'Long-term investment credit for farmland purchase'], ans: 1, exp: 'KCC provides farmers with timely, affordable credit for crop production (seeds, fertilisers, pesticides), post-harvest expenses, and allied activities — without complex paperwork each season.' },
  { q: 'The share of informal credit in rural India has changed from approximately what % in 1950s to now?', opts: ['From 30% to 90%', 'From 90% (informal) to 64% formal credit by 2012', 'From 50% to 50%', 'No significant change'], ans: 1, exp: 'In 1951, ~90% of rural credit came from informal sources (moneylenders). By 2003 formal sector provided 58%, and by 2012 about 64% of rural credit came from formal sources — a major shift.' },
  { q: 'The primary function of money in facilitating exchange is as:', opts: ['Store of value', 'Unit of account', 'Medium of exchange', 'Standard of deferred payment'], ans: 2, exp: 'The primary function of money is as a medium of exchange — it is universally accepted in exchange for goods and services, eliminating the need for double coincidence of wants in barter.' },
  { q: 'Cooperative banks differ from commercial banks in that:', opts: ['Cooperative banks are owned by the government', 'Cooperative banks are member-owned, usually serving agricultural and rural communities at lower interest', 'Cooperative banks only lend to corporations', 'Cooperative banks are not regulated by RBI'], ans: 1, exp: 'Cooperative banks are owned by their members (farmers, workers), operate at local/state level, provide cheaper credit to members, and focus on agricultural/rural credit — different from profit-driven commercial banks.' },
  { q: 'The RBI acts as a "banker\'s bank" because:', opts: ['It gives loans to individuals', 'It holds reserves of all commercial banks, lends to them in emergencies, and regulates their operations', 'It runs the largest bank in India', 'It sets interest on savings accounts'], ans: 1, exp: 'RBI is the banker\'s bank: it holds CRR reserves of commercial banks, provides emergency liquidity (LOLR — Lender of Last Resort), regulates and supervises banking operations, and clears inter-bank transactions.' },
  { q: 'The repo rate set by RBI is:', opts: ['The rate at which banks lend to customers', 'The rate at which RBI lends short-term money to commercial banks', 'The rate banks pay on savings accounts', 'The rate of return on government bonds'], ans: 1, exp: 'Repo Rate = Repurchase Option Rate — the rate at which RBI lends short-term (overnight) funds to commercial banks against government securities. Increasing repo rate reduces money supply and credit.' },
  { q: 'Microcredit differs from regular bank credit because it offers:', opts: ['Larger loan amounts at lower rates', 'Very small collateral-free loans to poor borrowers through group-based lending mechanisms', 'Loans only to agricultural sector', 'Credit cards with no interest'], ans: 1, exp: 'Microcredit provides tiny loans (from ₹1,000 to ₹50,000) to the poor without collateral, using social/group pressure for repayment, targeting people excluded from formal banking.' },
  { q: 'Jan Dhan Yojana (2014) aimed to:', opts: ['Build Jan Dan dams for irrigation', 'Ensure every household has a bank account, achieving financial inclusion of the unbanked', 'Provide Jan Dan cards for food', 'Establish new cooperative banks in rural areas'], ans: 1, exp: 'Pradhan Mantri Jan Dhan Yojana (2014) is a national financial inclusion mission — opening zero-balance bank accounts for every household, issuing RuPay debit cards, providing insurance and overdraft facilities.' },
  { q: 'UPI (Unified Payments Interface) in India allows:', opts: ['Only large corporate payments', 'Instant real-time inter-bank transfers using mobile phones, linked to bank accounts', 'International remittances only', 'Credit card payments only'], ans: 1, exp: 'UPI (2016, NPCI) enables instant transfer of money between bank accounts through mobile phones using unique Virtual Payment Addresses (VPAs) — revolutionising small and large digital payments in India.' },
  { q: 'Interest rates in the informal credit sector in India can range from:', opts: ['5-10% per annum', '12-15% per annum', '20-100%+ per annum', '2-5% per annum'], ans: 2, exp: 'Informal moneylenders, traders, and landlords charge 20-100% or more per annum, sometimes compounded daily or weekly. Compare to banks: 8-15% per annum for most loans.' },
  { q: 'Which of the following would NOT be acceptable as collateral for a bank loan?', opts: ['Land title deed', 'Gold ornaments', 'Fixed deposit certificate', 'A good credit history or word of honour alone'], ans: 3, exp: 'Banks require tangible, legally transferable assets as collateral. Good character or credit history alone is not accepted as collateral (though it influences approval). Physical assets can be seized if needed.' },
  { q: 'The primary reason rural poor are excluded from formal credit is:', opts: ['Banks don\'t operate in rural areas', 'Rural poor lack acceptable collateral, have no credit history, and paperwork requirements are complex', 'Rural poor refuse to use banks', 'RBI prohibits lending to rural poor'], ans: 1, exp: 'Rural poor lack: (1) acceptable collateral (no land titles, minimal assets), (2) documented income history, (3) banking access (distance), and face complex documentation requirements — pushing them to moneylenders.' },
  { q: 'The SLR (Statutory Liquidity Ratio) requires banks to hold a fraction of deposits in:', opts: ['Cash only with RBI', 'Liquid assets: cash, gold, and approved government securities', 'Government-approved project investments', 'Foreign currency reserves'], ans: 1, exp: 'SLR (set by RBI) requires banks to maintain a proportion of deposits in liquid assets: cash, gold, and/or approved government securities. Currently around 18% (varies). Complements CRR.' },
  { q: 'An SHG borrows money from banks after establishing its credibility. This is called:', opts: ['Refinancing', 'SHG-Bank linkage programme', 'Priority sector lending', 'Grameen model'], ans: 1, exp: 'The SHG-Bank Linkage Programme (NABARD promoted, from 1992) allows established SHGs to access formal bank credit, bridging the gap between informal community savings groups and the formal banking system.' },
  { q: 'Credit cards create risk for consumers because:', opts: ['They require good credit score', 'Unpaid credit card balances attract very high interest (24-48% per annum) and can spiral into debt', 'Banks can close accounts anytime', 'They are accepted only at large stores'], ans: 1, exp: 'Credit cards charge very high interest (often 2-4% per month = 24-48% per annum compounded) on unpaid balances. Minimum payment traps are common, leading to debt spirals.' },
  { q: 'What percentage of Grameen Bank borrowers are women?', opts: ['30%', '50%', '75%', '97%'], ans: 3, exp: 'About 97% of Grameen Bank borrowers are women. Yunus found women more reliable in repayment and that loans to women benefit entire families (children\'s education, nutrition) more than loans to men.' },
  { q: 'Formal credit is said to have "greater reach" than informal credit for what reason?', opts: ['Formal credit is always cheaper', 'Formal credit doesn\'t reach many rural areas, but where it does, it provides regulated, documented credit to more people at lower rates', 'Formal credit is given to all without collateral', 'Formal sector has more money to lend'], ans: 1, exp: 'Where formal credit (banks, cooperatives) is accessible, it offers regulated interest rates (8-15%), documented transactions, and multiple products — making credit safer and potentially more affordable than informal alternatives.' },
  { q: 'The Microfinance revolution is significant for rural women because:', opts: ['It gives women government jobs', 'It provides access to credit for income-generating activities, building financial independence and confidence', 'It gives free land to women', 'It provides free school for women\'s children'], ans: 1, exp: 'Microfinance enables rural women to start or expand small enterprises (tailoring, goat-rearing, food processing), generate income, reduce dependence on husbands, and build financial literacy and self-confidence.' },
  { q: 'Which of the following is NOT a function of money?', opts: ['Medium of exchange', 'Store of value', 'Unit of account', 'Guarantee of happiness/well-being'], ans: 3, exp: 'Money\'s four functions are: medium of exchange, store of value, unit of account, and standard of deferred payment. Money can buy goods that contribute to happiness, but is not itself a guarantee of wellbeing.' },
  { q: 'Credit creates economic value when:', opts: ['It is stored in banks', 'It enables productive investment that generates returns exceeding the interest cost', 'It reduces tax burden', 'The government borrows it'], ans: 1, exp: 'Credit creates value when borrowed funds are used productively (starting a business, buying equipment, education) and generate returns (income, profits) that exceed the interest cost — enabling growth.' },
  { q: 'India\'s "thin banking" in rural areas historically resulted from:', opts: ['Low population density in villages', 'Branch banking policies that kept banks mainly in cities; commercial banks found rural lending unprofitable', 'Villagers refusing to open bank accounts', 'RBI restrictions on rural banking'], ans: 1, exp: 'Commercial banks traditionally concentrated in urban/semi-urban areas as rural lending was seen as costly (small loans, high monitoring costs, low deposits). RBI\'s priority sector lending mandates tried to address this.' },
  { q: 'The Reserve Bank of India was established in:', opts: ['1919', '1935', '1947', '1952'], ans: 1, exp: 'RBI was established on 1 April 1935 under the Reserve Bank of India Act 1934. It was nationalised in 1949. It is India\'s central bank and monetary authority.' },
  { q: 'Money as "standard of deferred payment" means:', opts: ['It is used for future repayment of debts (loans, credit)', 'Payments are delayed by the government', 'Deferred taxes are paid in money', 'Money loses value slowly over time'], ans: 0, exp: 'Standard of deferred payment: money allows debts to be contracted now and paid later — you borrow today and repay with money in the future. This function makes credit systems possible.' }
];

const SOCIAL_CH9_EXTRA = [
  { q: 'Which of the following is NOT a function of political parties?', opts: ['Contest elections and nominate candidates', 'Form and run government', 'Make laws in legislature', 'Determine Supreme Court judgments'], ans: 3, exp: 'Political parties contest elections, form government, and legislate — but they cannot determine Supreme Court judgments. The judiciary is independent of political parties.' },
  { q: 'A one-party system is found in which country?', opts: ['USA', 'India', 'China', 'Germany'], ans: 2, exp: 'China has a one-party system — only the Chinese Communist Party (CCP) is allowed to govern. Other parties may exist but cannot challenge the CCP\'s monopoly on power.' },
  { q: 'The USA is an example of a:', opts: ['One-party system', 'Two-party system', 'Multi-party system', 'No-party system'], ans: 1, exp: 'USA has a two-party system dominated by Democrats and Republicans. Third parties rarely win significant seats due to the "first-past-the-post" electoral system.' },
  { q: 'In India, for a party to be recognised as a "national party" by the Election Commission, it must win at least:', opts: ['2% of Lok Sabha seats from any states', '6% votes in LS election + 4 Lok Sabha seats, OR 2% LS seats from 3+ states', '10 Lok Sabha seats from 5 states', '20% votes in any national election'], ans: 1, exp: 'National Party recognition criteria: (1) 6% valid votes in Lok Sabha or state elections in 4 states + 4 LS seats; OR (2) At least 2% of LS total seats (11+ seats) from 3 or more states.' },
  { q: 'Which party was accorded national party status by the Election Commission of India in 2023?', opts: ['BSP', 'AAP (Aam Aadmi Party)', 'Trinamool Congress', 'TDP'], ans: 1, exp: 'Aam Aadmi Party (AAP) was recognised as a national party in 2023 after winning governments in Delhi and Punjab, giving it national party status in multiple states.' },
  { q: 'The Anti-Defection Law (10th Schedule) was added to the Indian Constitution by:', opts: ['44th Amendment 1978', '52nd Amendment 1985', '61st Amendment 1988', '73rd Amendment 1992'], ans: 1, exp: 'The Anti-Defection Law was added by the 52nd Constitutional Amendment 1985 during Rajiv Gandhi\'s government, inserting the 10th Schedule to prevent elected members from switching parties.' },
  { q: '"Aaya Ram Gaya Ram" became famous in Indian politics because it referred to:', opts: ['A politician who visited USA and returned', 'Gaya Lal (Haryana MLA, 1967) who changed parties three times in one day, symbolising unprincipled defection', 'A party leader who kept coming and going', 'The ritual of welcoming new party members'], ans: 1, exp: 'Haryana MLA Gaya Lal switched parties three times in a single day (1967), prompting the phrase "Aaya Ram Gaya Ram" (Ram came, Ram went). This popularised the term "defection" in Indian politics.' },
  { q: 'Under the Anti-Defection Law, an elected member is disqualified if:', opts: ['They criticise their party in public', 'They vote against the party\'s whip or voluntarily give up party membership', 'They fail to attend Parliament/assembly regularly', 'They contest elections for a second time'], ans: 1, exp: '10th Schedule: A member is disqualified if (1) they voluntarily give up party membership, or (2) they vote or abstain contrary to the party\'s direction (whip) without party permission.' },
  { q: 'The decision on anti-defection is made by:', opts: ['Supreme Court', 'President of India', 'Speaker of Lok Sabha / Chairman of Rajya Sabha', 'Election Commission'], ans: 2, exp: 'Anti-defection cases are decided by the Speaker of the Lok Sabha (or Chairman of Rajya Sabha for RS cases), or the Speaker/Chairman of state assemblies — a controversial power as Speaker is from the ruling party.' },
  { q: 'Reserved Symbol for political parties means:', opts: ['Parties can reserve their party name', 'Recognised national/state parties get an exclusive symbol that no other candidate can use', 'Symbols are kept secret until election day', 'Religious symbols are reserved for no party to use'], ans: 1, exp: 'Election Commission allots exclusive reserved symbols (like lotus, hand, elephant) to recognised national and state parties — independent/unrecognised candidates can only use symbols from the "free" common pool.' },
  { q: 'NOTA (None of the Above) was introduced in Indian elections following a Supreme Court order in:', opts: ['2009', '2012', '2013', '2015'], ans: 2, exp: 'The Supreme Court in 2013 (PUCL vs Union of India) directed the Election Commission to provide a NOTA (None of the Above) option on EVMs, allowing voters to reject all candidates.' },
  { q: 'EVM (Electronic Voting Machine) was first used on a trial basis in Indian elections in:', opts: ['1977', '1982', '1991', '2004'], ans: 1, exp: 'EVMs were first used in 50 constituencies (Kerala) during the 1982 Kerala state assembly election. Full deployment in all Lok Sabha constituencies happened in 2004.' },
  { q: 'VVPAT (Voter Verifiable Paper Audit Trail) was introduced in:', opts: ['2009', '2014', '2017', '2019'], ans: 2, exp: 'VVPAT was introduced and piloted from 2013, and deployed in all polling stations for the 2017 state elections and 2019 Lok Sabha elections. It prints a paper slip the voter can see for 7 seconds.' },
  { q: 'Dynastic succession as a challenge to political parties refers to:', opts: ['Kings becoming party leaders', 'Family members of political leaders dominating party leadership, limiting entry of capable outsiders', 'Old dynasty parties being dissolved', 'Party leaders being too old (dynastic age)'], ans: 1, exp: 'Dynastic politics means children/relatives of established leaders become next leaders by virtue of family connection, not merit or democratic selection — reducing internal democracy and party renewal.' },
  { q: 'Criminalisation of politics refers to:', opts: ['Parties advocating for criminals\' rights', 'Election of persons with serious criminal records to legislative bodies', 'Politicians making laws that benefit criminals', 'Police officers contesting elections'], ans: 1, exp: 'Criminalisation of politics = increasing number of MPs and MLAs with pending criminal cases (including serious crimes like murder, rape, extortion) — many get elected because of, not despite, criminal backgrounds.' },
  { q: 'Which of the following is a challenge to internal democracy of parties?', opts: ['Too many candidates contesting elections', 'Ordinary party members having no say in candidate selection or policy — decisions made by top leaders', 'Too many parties competing', 'Courts interfering in party decisions'], ans: 1, exp: 'Most parties lack internal democracy — leaders at the top select candidates, make policy, and control party funds without consulting ordinary members, making parties oligarchies not democratic bodies.' },
  { q: 'Electoral bonds (introduced 2018) face criticism primarily because:', opts: ['They are difficult to purchase', 'They allow anonymous funding of parties, making political funding opaque and enabling possible corporate influence', 'They can only be used by small parties', 'They are only available in large denominations'], ans: 1, exp: 'Electoral bonds allow anyone to buy bonds from SBI and donate to parties anonymously — only the government knows who funded which party, creating concerns about corporate capture of politics and quid pro quo.' },
  { q: 'A "party with a difference" or "party system with a difference" in India refers to:', opts: ['BJP\'s slogan', 'India\'s multi-party system where numerous parties have broad ideological diversity and regional variation', 'AAP\'s claim of anti-corruption', 'The coalition government model'], ans: 1, exp: 'India\'s party system is distinctive: unlike USA/UK\'s two-party system, India has 6 national parties plus dozens of state parties, representing diverse ideological, regional, caste, linguistic, and religious interests.' },
  { q: 'The Left wing in politics is associated with:', opts: ['Free market, low taxes, traditional values', 'Government intervention, redistribution, social equality, workers\' rights', 'Strong military and nationalism', 'Religious conservatism'], ans: 1, exp: 'Left wing politics advocates: government intervention to reduce inequality, workers\' rights, universal welfare (education, health), progressive taxes, and social justice. Examples: CPI, CPI(M) in India.' },
  { q: 'The Right wing in politics is associated with:', opts: ['Equality and redistribution', 'Free market economics, private enterprise, traditional values, strong nationalism', 'Abolition of private property', 'International cooperation over national sovereignty'], ans: 1, exp: 'Right wing politics advocates: free markets, low government intervention in economy, private enterprise, national sovereignty, traditional cultural values. Examples: BJP in India, Republicans in USA.' },
  { q: 'RTI Act 2005 (Right to Information) can be used to improve political accountability by:', opts: ['Allowing citizens to vote parties out directly', 'Enabling citizens to demand information about government decisions, expenditure, and policy implementation', 'Requiring parties to publish their manifesto', 'Making all party meetings public'], ans: 1, exp: 'RTI empowers citizens to demand information from government bodies — exposing corruption, misuse of funds, and poor policy implementation. It strengthens accountability even though political parties have resisted its application to them.' },
  { q: 'How many national parties were recognised by the Election Commission of India in 2023?', opts: ['4', '6', '8', '10'], ans: 1, exp: 'As of 2023, the Election Commission recognised 6 national parties: INC (Congress), BJP, BSP, CPI(M), NCP, and AAP. Many previously national parties (NCP, Trinamool) lost the status.' },
  { q: 'State/Regional parties are recognised when they win:', opts: ['10% of votes in any election', '6% votes in state election + 2 state assembly seats, OR 3% of state assembly seats', '5 Lok Sabha seats from the state', '20% of the state\'s seats in Parliament'], ans: 1, exp: 'State Party recognition: 6% valid votes in state election AND 2 MLAs, OR win 3% (minimum 3 seats) of state assembly seats, OR win 1 Lok Sabha seat per 25 state assembly seats.' },
  { q: 'Coalition politics has become the norm in India since:', opts: ['1947', '1967 (first non-Congress state governments)', '1989 (no single majority at Centre)', '2004'], ans: 2, exp: 'Since 1989, no single party has won an outright majority in Lok Sabha. Coalition governments (VP Singh\'s Janata Dal, NDA, UPA) have governed continuously, making coalition-building essential.' },
  { q: 'Ideological differences between parties are important because they:', opts: ['Create confusion among voters', 'Allow voters to choose between different visions of governance — free market vs welfare, secular vs religious, etc.', 'Are irrelevant in actual governance', 'Cause political violence'], ans: 1, exp: 'Ideological differences between parties give voters real choices about the direction of governance: economic policies (privatisation vs welfare), social policies (secularism vs religious nationalism), and foreign policy approaches.' },
  { q: 'The term "hung parliament" or "hung assembly" means:', opts: ['Parliament that cannot pass any law', 'No single party or pre-election alliance has a majority of seats', 'Parliament session that runs past midnight', 'Parliament with too many members'], ans: 1, exp: 'A hung parliament/assembly means no single party has a simple majority (50%+1 seats). Governments are formed through post-election coalitions or minority governments supported by outside parties.' },
  { q: 'The anti-defection law has been criticised because:', opts: ['It prevents all party-switching including on conscience grounds', 'The Speaker who decides anti-defection cases is from the ruling party, creating a conflict of interest', 'It doesn\'t apply to Rajya Sabha', 'It was introduced without constitutional amendment'], ans: 1, exp: 'The main criticism: the Speaker (who decides anti-defection cases) belongs to the ruling party and is often appointed by it, creating a structural conflict of interest — disqualification decisions can be politically motivated.' },
  { q: 'Parties shape public opinion primarily through:', opts: ['Supreme Court orders', 'Media campaigns, political rallies, party manifestos, and social media outreach', 'Military force', 'Educational curriculum changes'], ans: 1, exp: 'Parties shape public opinion through: election manifestos, rallies, press releases, TV/social media campaigns, and through their MPs/MLAs raising issues in Parliament — creating political narratives for voters.' },
  { q: 'The Election Commission of India derives its authority from:', opts: ['Parliament\'s legislation', 'Article 324 of the Constitution', 'The President\'s order', 'An act passed in 1952'], ans: 1, exp: 'Article 324 of the Constitution vests superintendence, direction, and control of elections in the Election Commission of India. The Chief Election Commissioner is constitutionally protected.' },
  { q: 'A "whip" in parliamentary party politics is:', opts: ['A physical instrument used for discipline', 'An official direction from party leadership on how members should vote on a specific issue', 'The party spokesperson who handles media', 'A committee that drafts party manifesto'], ans: 1, exp: 'A whip is an official party directive (issued by the "Chief Whip") telling MPs/MLAs how to vote on bills or motions. Violating a 3-line whip (strongest form) can trigger anti-defection proceedings.' },
  { q: 'The need for political parties arises primarily because:', opts: ['Government requires parties by law', 'In large democracies, individual candidates cannot represent the diverse interests of millions — parties aggregate and articulate common interests', 'Elections cannot be held without parties', 'The Constitution mandates parties'], ans: 1, exp: 'Modern democracies require parties because: elections across millions of voters need organised contestants, governance requires coordinated legislation, and diverse citizen interests need aggregation and representation.' },
  { q: 'The role of opposition parties in a democracy is BEST described as:', opts: ['Obstructing government policies', 'Critiquing government, offering alternatives, holding government accountable, and representing those who voted against the ruling party', 'Waiting to come to power', 'Helping government pass laws'], ans: 1, exp: 'A healthy democracy requires a strong opposition: scrutinising government decisions, exposing corruption, offering policy alternatives, representing those who voted against the government, and checking the abuse of power.' },
  { q: 'Political parties face the challenge of becoming relevant to younger voters because:', opts: ['Young people have low voting rates', 'Traditional parties often have rigid structures, older leaders, and outdated communication methods that don\'t connect with youth', 'Youth are not allowed to join parties', 'Youth prefer military governments'], ans: 1, exp: 'Many traditional parties have hierarchical structures, elderly leadership, and communication methods (party rallies, print media) that don\'t resonate with digital-native youth who prefer social media engagement and new issues (environment, jobs).' },
  { q: 'The concept of "loyal opposition" in democracy means:', opts: ['Opposition that always agrees with the government', 'An opposition that accepts the legitimacy of the system while vigorously opposing the government\'s policies', 'Opposition parties that form coalition with ruling party', 'Opposition committed to party loyalty above national interest'], ans: 1, exp: '"Loyal opposition" means opposition parties accept the democratic system and constitutional order (loyal to the nation) while opposing the ruling party\'s policies — essential for stable democracy.' },
  { q: 'Political parties provide "social access to government" meaning:', opts: ['Parties build social media pages for government', 'Parties serve as channels through which ordinary citizens can communicate needs to government and seek redress', 'Parties organise social events for government officials', 'Parties provide scholarships for social work students'], ans: 1, exp: 'Political parties (through local leaders, MLAs, MPs) help ordinary citizens navigate government bureaucracy, access welfare schemes, get local problems addressed — bridging citizens and state machinery.' },
  { q: 'The comparison between parties with same names across different democracies shows that:', opts: ['Democratic and Republican mean the same in all countries', 'Party names don\'t reflect ideology — content (policies) matters more than labels', 'All socialist parties have identical policies', 'Right-wing parties are the same globally'], ans: 1, exp: 'Party labels don\'t have universal meaning — "Democratic Party" in USA is different from "Democratic parties" in other countries. You must look at actual policies, not just names, to understand ideology.' },
  { q: 'The number of parties in India\'s multi-party system results in:', opts: ['Political instability always', 'Coalition governments but also representation of diverse regional, linguistic, caste, and ideological interests', 'No government formation being possible', 'Single-party dominance'], ans: 1, exp: 'India\'s multi-party system (1000+ registered parties, 6 national + many state parties) leads to coalition governments but also ensures that diverse regions, communities, and ideologies have representation — reflecting India\'s plural society.' }
];

const SOCIAL_CH10_EXTRA = [
  { q: 'MNCs locate production in developing countries primarily because of:', opts: ['Better technology in developing countries', 'Cheap labour, raw materials, proximity to markets, and lower environmental regulations', 'Developing countries force them to invest', 'WTO requires production in developing countries'], ans: 1, exp: 'MNCs seek developing countries for: cheap labour (wages 5-20x lower than home countries), raw material access, large consumer markets, lower taxes (SEZs), and less stringent environmental/labour regulations.' },
  { q: 'FDI (Foreign Direct Investment) differs from FII (Foreign Institutional Investment) in that FDI:', opts: ['Is always larger in amount', 'Involves physical investment in factories, infrastructure, or real businesses (long-term)', 'Can be withdrawn instantly from stock markets', 'Is only from government-to-government'], ans: 1, exp: 'FDI = investment in real physical assets (building factories, acquiring companies) — long-term commitment. FII = portfolio investment in stocks/bonds — can be withdrawn quickly ("hot money"), making FII more volatile.' },
  { q: 'India\'s 1991 LPG reforms (Liberalisation, Privatisation, Globalisation) were initiated due to:', opts: ['Voluntary decision to embrace free trade', 'Severe Balance of Payments crisis — forex reserves fell to 2-week import cover, IMF loan conditional on reforms', 'WTO pressure on India', 'American demand for Indian market access'], ans: 1, exp: 'India\'s 1991 crisis: oil price shock (Gulf War), political instability, and mismanagement left India with only $1 billion forex (2 weeks of imports). IMF loan of $1.8 billion required market liberalisation as condition.' },
  { q: 'P.V. Narasimha Rao was Prime Minister when India\'s 1991 economic reforms were implemented. Who was Finance Minister?', opts: ['Manmohan Singh', 'P. Chidambaram', 'Pranab Mukherjee', 'Yashwant Sinha'], ans: 0, exp: 'Dr. Manmohan Singh was Finance Minister under PM Narasimha Rao during the 1991 reforms. His landmark budget (July 1991) launched LPG reforms that transformed India\'s economy.' },
  { q: 'SEZ (Special Economic Zone) Act was passed in India in:', opts: ['1991', '2000', '2005', '2010'], ans: 2, exp: 'India\'s SEZ Act was passed in 2005 and came into force in 2006. SEZs offer: 100% FDI in most sectors, tax holidays (5 years), single-window clearance, and duty-free imports for export production.' },
  { q: 'Before 1991, India\'s average import tariff was approximately:', opts: ['10-15%', '25-30%', '50-75%', '90-100%'], ans: 2, exp: 'India\'s average tariff before 1991 reforms was about 72-80% — extremely high. By 2001, it had been reduced to about 25%, and further reductions followed WTO commitments.' },
  { q: 'WTO (World Trade Organisation) has how many member countries (as of 2023)?', opts: ['120', '140', '164', '195'], ans: 2, exp: 'WTO has 164 member countries (as of 2016, when Afghanistan and Liberia joined). The WTO was established in 1995, replacing GATT (1947) with a stronger dispute settlement mechanism.' },
  { q: 'TRIPS (Trade-Related Intellectual Property Rights) is significant for India because:', opts: ['It protects India\'s traditional knowledge', 'It requires 20-year patent protection, limiting India\'s ability to produce cheap generic medicines', 'It allows India to copy foreign technology', 'It protects Indian software from piracy'], ans: 1, exp: 'TRIPS (WTO, 1994) requires 20-year product patents — MNC pharma companies can block generic versions. Doha Declaration 2001 allowed "compulsory licensing" for public health emergencies, protecting India\'s generic industry.' },
  { q: 'India\'s pharmaceutical industry is called "pharmacy of the world" because:', opts: ['India has the most expensive medicines', 'India is the world\'s largest exporter of generic medicines, supplying 60%+ of global vaccine demand and low-cost generics', 'India invented the most medicines', 'India imports the most pharmaceutical ingredients'], ans: 1, exp: 'India\'s generic pharmaceutical industry (based in Hyderabad, Ahmedabad, Mumbai) supplies 60%+ of global vaccines, 40% of generic drugs to USA, and low-cost generics to developing countries — making healthcare affordable globally.' },
  { q: 'The Doha Round of WTO negotiations (2001-present) has repeatedly stalled because:', opts: ['WTO cannot hold meetings', 'Rich countries (USA, EU) refuse to reduce agricultural subsidies that harm developing country farmers', 'Developing countries want to leave WTO', 'China and India disagree'], ans: 1, exp: 'Doha Round (launched 2001 for development) stalled over agriculture: USA and EU subsidise farmers ($100bn+ annually), making their food artificially cheap and undercutting developing country farmers — something developed countries refused to change.' },
  { q: 'Container shipping revolutionised global trade because:', opts: ['Containers are made of steel, making them strong', 'Standardised containers drastically reduced loading/unloading costs and time at ports, making global trade cheap', 'Containers can hold more volume than previous ships', 'Containers are tracked by GPS'], ans: 1, exp: 'Standardised containers (introduced 1950s-60s) could be transferred between ships, trucks, and trains without unpacking — reducing port time from days to hours and cargo handling costs by 90%, enabling cheap global trade.' },
  { q: 'IT companies in India successfully exported services because:', opts: ['India had the cheapest internet', 'India had large pool of English-speaking, technically skilled graduates at much lower wages than USA/Europe', 'USA companies were forced to outsource to India', 'Indian IT quality is uniquely superior'], ans: 1, exp: 'India\'s IT/BPO advantage: large pool of English-speaking engineering graduates, 8x lower wages than USA (a $70,000/yr US programmer costs ~$8,000/yr in India), quality education (IITs/NITs), and infrastructure in tech hubs.' },
  { q: 'Globalisation has hurt India\'s ________ sector most directly through import competition:', opts: ['IT/Software', 'Small manufacturing (toys, footwear, plastics)', 'Agriculture (rice and wheat)', 'Banking'], ans: 1, exp: 'Small Indian manufacturers of toys, footwear, plastic goods, and electronics faced severe competition from cheaper Chinese imports after 1991 liberalisation, leading to factory closures and job losses.' },
  { q: 'The "race to the bottom" in the context of globalisation refers to:', opts: ['Companies competing to produce lowest quality goods', 'Countries reducing labour and environmental standards to attract MNCs in a competitive disadvantage spiral', 'WTO reducing tariffs to zero over time', 'Wages falling globally due to automation'], ans: 1, exp: '"Race to the bottom": countries compete to attract MNC investment by offering lowest wages, weakest labour laws, and minimal environmental regulations — MNCs exploit this competition to maximise profits.' },
  { q: 'Fair Trade movement certifies products to ensure:', opts: ['Products meet food safety standards', 'Producers in developing countries receive fair prices, decent wages, and safe working conditions', 'Products are cheapest in the market', 'Products are manufactured without child labour only'], ans: 1, exp: 'Fair Trade certification (Fair Trade International, WFTO) ensures producers in developing countries get minimum price guarantees, community development premiums, and decent working conditions — for coffee, cocoa, tea, bananas.' },
  { q: 'India\'s current account deficit (CAD) means:', opts: ['Government budget is in deficit', 'India imports more goods and services than it exports, requiring foreign capital inflows to fund the gap', 'India has more foreign debt than assets', 'India\'s banking sector has a deficit'], ans: 1, exp: 'Current Account Deficit = value of imports (goods + services + income) exceeds value of exports. India typically runs a CAD because it imports more goods (especially oil, gold, electronics) than it exports.' },
  { q: 'ASEAN (Association of Southeast Asian Nations) is relevant to India\'s globalisation because:', opts: ['ASEAN headquarters is in India', 'India has Free Trade Agreements with ASEAN, linking Indian markets to 10 SE Asian economies', 'ASEAN funds India\'s infrastructure', 'ASEAN blocks Indian exports to SE Asia'], ans: 1, exp: 'ASEAN-India FTA (2010) connects India\'s economy to 10 SE Asian nations (Indonesia, Malaysia, Singapore, Thailand, etc.), reducing tariffs on goods trade and boosting integration of supply chains.' },
  { q: 'The Washington Consensus policies that India adopted in 1991 included:', opts: ['Nationalisation of private companies', 'Trade liberalisation, deregulation, privatisation of public enterprises, and fiscal austerity', 'Price controls on essential goods', 'Increase in import tariffs'], ans: 1, exp: 'Washington Consensus (IMF/World Bank prescriptions): reduce government fiscal deficit, liberalise trade (reduce tariffs), deregulate domestic markets, privatise state enterprises, and attract FDI.' },
  { q: 'India\'s EXIM Policy governs:', opts: ['Exchange rates between rupee and dollar', 'Rules and incentives for India\'s export and import trade', 'External aid received from foreign countries', 'Indian investments overseas (FDI from India)'], ans: 1, exp: 'India\'s Foreign Trade Policy (EXIM Policy) sets rules for imports/exports: tariff rates, export promotion schemes (MEIS, SEIS), SEZs, export obligation under advance licence, and prohibited items.' },
  { q: 'Outsourcing of IT services from USA to India creates which type of globalisation controversy?', opts: ['Cultural imperialism', '"Offshoring" debate — USA jobs going to India but consumers get cheaper services; India gains employment and skills', 'Technology theft accusation', 'Environmental concerns'], ans: 1, exp: 'Offshoring IT jobs to India reduces US jobs in those roles (political controversy in USA) but consumers benefit from cheaper services, India gains employment and forex, and MNCs gain profits — complex trade-offs.' },
  { q: 'India\'s gem and jewellery exports contribute to globalisation how?', opts: ['India exports raw diamonds', 'India imports rough diamonds/gemstones, adds value by cutting and polishing, and exports jewellery — a key global value chain', 'India doesn\'t export gems', 'India exports synthetic gems only'], ans: 1, exp: 'India imports rough diamonds (from Africa/Australia via Antwerp/Dubai), cuts and polishes them in Surat, Mumbai, and exports polished diamonds/jewellery globally — India handles 90% of world\'s diamond cutting and polishing.' },
  { q: 'The Global Value Chain (GVC) concept in modern manufacturing means:', opts: ['Only one country makes a product completely', 'Different stages of production occur in different countries based on comparative advantage', 'Value is created only in developed countries', 'Products are made in a single global factory'], ans: 1, exp: 'GVCs: iPhone designed in USA, chips from Taiwan (TSMC), assembled in China (Foxconn), sold globally. Different countries handle stages where they have cost/skill advantages, integrating into one global production system.' },
  { q: 'India\'s foreign exchange reserves in 2023 were approximately:', opts: ['$100 billion', '$300 billion', '$500-600 billion', '$1 trillion'], ans: 2, exp: 'India\'s forex reserves were approximately $580-620 billion in 2023 — one of the world\'s largest, providing import cover of 9-10 months and cushion against currency volatility.' },
  { q: 'The "Make in India" initiative is related to globalisation because it aims to:', opts: ['Replace all imports with Indian products', 'Attract global MNCs to manufacture in India, making India part of global supply chains while creating domestic jobs', 'Ban foreign products in India', 'Force Indian companies to export everything'], ans: 1, exp: '"Make in India" (2014) aims to attract global manufacturers (phones, electronics, defence) to produce in India — leveraging globalisation\'s FDI flows to build domestic manufacturing capacity and create jobs.' },
  { q: 'The 1973 OPEC oil embargo had what effect on developing countries\' globalisation?', opts: ['Helped developing countries by raising their oil revenues', 'Massively increased oil import bills for oil-importing developing countries, worsening their balance of payments', 'Had no effect on developing countries', 'Ended globalisation completely'], ans: 1, exp: '1973 OPEC oil price quadrupling devastated oil-importing developing countries: India\'s oil import bill surged, causing current account deficits and reducing development spending. Many countries borrowed heavily, leading to the 1980s debt crisis.' },
  { q: 'Which institution would India approach if facing a severe balance of payments crisis requiring emergency loans?', opts: ['World Bank', 'IMF (International Monetary Fund)', 'WTO', 'Asian Development Bank'], ans: 1, exp: 'IMF provides short-term balance-of-payments support (emergency loans) to countries facing currency crises or import payment difficulties. India borrowed from IMF in 1966, 1981, and 1991.' },
  { q: 'Digital globalisation refers to:', opts: ['Use of digital devices in developing countries', 'Cross-border flows of data, information, digital services, and e-commerce connecting global markets', 'Globalisation of digital currency only', 'Internet access in developing countries'], ans: 1, exp: 'Digital globalisation = internet-enabled global flows of data (Netflix, Google), digital services (software, BPO), e-commerce (Amazon, Alibaba), and remote work — the newest and fastest-growing form of globalisation.' },
  { q: 'India benefited from globalisation in the IT sector primarily during:', opts: ['1947-1970', '1970-1990', '1991-2010', '2010-present only'], ans: 2, exp: 'India\'s IT boom occurred 1991-2010: 1991 reforms liberalised telecommunications, 1995 internet commercialisation, Y2K problem (1999) gave Indian IT companies global contracts, and Bengaluru/Hyderabad emerged as global tech hubs.' },
  { q: 'The negative impact of globalisation on Indian farmers includes:', opts: ['Higher prices for crops due to global demand', 'Exposure to volatile global commodity prices and competition from subsidised foreign food imports', 'Access to better seeds from global companies', 'Higher MSP (Minimum Support Price) due to global prices'], ans: 1, exp: 'Indian farmers face: price volatility of global commodity markets (cotton, soybean prices crashing hurt farmers), competition from subsidised EU/US farm products, and input cost increases from global inflation.' },
  { q: 'Hyderabad is a major centre for which globalised industry in India?', opts: ['Textile exports', 'Pharmaceutical industry and IT/software', 'Diamond cutting and polishing', 'Tea and coffee exports'], ans: 1, exp: 'Hyderabad (Telangana) is India\'s major pharmaceutical hub (Dr. Reddy\'s, Aurobindo, Hetero) — "Pharma City" — and also a significant IT hub (HITEC City), with global pharmaceutical and IT exports.' },
  { q: 'Trade deficit in India is worsened primarily by imports of:', opts: ['Textiles and garments', 'Crude oil, gold, and electronic goods', 'Agricultural commodities', 'Software services'], ans: 1, exp: 'India\'s trade deficit is driven mainly by: crude oil and petroleum products (~$130bn/yr), gold (~$40bn/yr), and electronic goods (~$70bn/yr) — these three categories account for most of India\'s import bill.' },
  { q: 'The Doha Declaration (2001) on TRIPS and Public Health allowed developing countries to:', opts: ['Export generic medicines without patent approval', 'Issue compulsory licences to produce generic versions of patented medicines for public health emergencies', 'Ignore TRIPS entirely', 'Set their own patent terms shorter than 20 years'], ans: 1, exp: 'Doha Declaration (2001) clarified TRIPS allows "compulsory licensing" — governments can allow local production of generic versions of patented medicines (without patent holder consent) during public health emergencies like HIV/AIDS.' },
  { q: 'Globalisation of production means that a single product like an iPhone is produced by:', opts: ['Entirely in USA where it is designed', 'Components manufactured in different countries (Korea, Taiwan, China, Japan) and assembled in China', 'All in one Asian country for efficiency', 'Independently by each country for its own market'], ans: 1, exp: 'iPhone production is a global value chain: designed in USA, processors from Korea (Samsung) and Taiwan (TSMC), cameras from Japan, assembled by Foxconn in China, distributed globally — no single country makes it.' },
  { q: 'Foreign Exchange (Forex) Reserves serve which primary function?', opts: ['Finance government\'s fiscal deficit', 'Provide cushion for import payments, currency stability, and crisis management', 'Fund domestic infrastructure projects', 'Provide interest income to government'], ans: 1, exp: 'Forex reserves: provide import payment cover (if exports/FDI fall), stabilise the rupee (RBI buys/sells dollars), service foreign debt, and act as confidence signal to investors and credit rating agencies.' },
  { q: 'The ASEAN-India Free Trade Agreement (2010) primarily covers:', opts: ['Services only', 'Trade in goods, reducing tariffs between India and 10 ASEAN countries', 'Military cooperation', 'Technology transfer from ASEAN to India'], ans: 1, exp: 'ASEAN-India FTA on goods (2010) eliminated or reduced tariffs on about 80% of goods traded between India and 10 ASEAN nations. A separate agreement covers services (2015).' },
  { q: 'The "China plus one" strategy of global supply chains means:', opts: ['All products require 1 Chinese component', 'Companies diversifying production away from China to other countries (India, Vietnam) to reduce geopolitical risk', 'China plus one is China\'s development model', 'WTO allowing China one extra trade exception'], ans: 1, exp: '"China + 1" strategy: after US-China trade war (2018+) and COVID supply chain disruptions, global companies are adding production capacity in Vietnam, India, Mexico alongside (not replacing) China to reduce dependence.' }
];
